        A, B, C = parts[0], parts[1], parts[2]
        la, lb, lc = len(A), len(B), len(C)

        def kmp_find_all(text, pattern):
            if not pattern:
                return list(range(len(text) + 1))
            m = len(pattern)
            tn = len(text)
            fail = [0] * m
            k = 0
            for i in range(1, m):
                while k > 0 and pattern[k] != pattern[i]:
                    k = fail[k - 1]
                if pattern[k] == pattern[i]:
                    k += 1
                fail[i] = k
            res = []
            k = 0
            for i in range(tn):
                while k > 0 and pattern[k] != text[i]:
                    k = fail[k - 1]
                if pattern[k] == text[i]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = fail[k - 1]
            return res

        occA = kmp_find_all(s, A)
        occB = kmp_find_all(s, B)
        occC = kmp_find_all(s, C)

